(x, y, t) => {
  const cx = 240, cy = 120;
  const wx = Math.sin(x*0.02+t*0.3)*15+Math.cos(y*0.015-t*0.2)*10+Math.sin(x*0.045+y*0.03+t*0.7)*5;
  const wy = Math.cos(y*0.02-t*0.25)*15+Math.sin(x*0.018+t*0.35)*10+Math.cos(x*0.035-y*0.04-t*0.6)*5;
  const sx = x+wx, sy = y+wy;
  const wx2 = Math.sin(sx*0.03+t*0.5)*8+Math.cos(sy*0.025-t*0.4)*6;
  const wy2 = Math.cos(sy*0.03-t*0.45)*8+Math.sin(sx*0.028+t*0.55)*6;
  const fx = sx+wx2, fy = sy+wy2;
  const src = [
    [160+Math.sin(t*0.6)*100,80+Math.cos(t*0.4)*50,0.08,2.0,0.06,1.3],
    [320+Math.cos(t*0.5)*100,160+Math.sin(t*0.7)*50,0.1,1.7,0.08,1.1],
    [240+Math.sin(t*0.3+2)*140,120+Math.cos(t*0.5+1)*90,0.06,2.3,0.04,1.5],
    [120+Math.cos(t*0.8+1)*80,180+Math.sin(t*0.6+3)*60,0.12,1.5,0.09,0.9],
    [360+Math.sin(t*0.4+4)*90,60+Math.cos(t*0.9+2)*70,0.07,2.6,0.05,1.4],
    [240+Math.cos(t*0.35+5)*120,200+Math.sin(t*0.55)*80,0.09,1.9,0.07,1.2]
  ];
  let aS=0,iS=0,aS2=0,iS2=0;
  for(const[sX,sY,f,sp,f2,sp2]of src){
    const d=Math.sqrt((fx-sX)**2+(fy-sY)**2);
    aS+=Math.sin(d*f-t*sp);iS+=Math.sin(d*f*0.7+t*sp*0.6+1.5);
    aS2+=Math.sin(d*f2*1.5-t*sp2);iS2+=Math.sin(d*f2+t*sp2*0.8+2.0);
