  const act=aS/6,inh=iS/6,act2=aS2/6,inh2=iS2/6;
  const bg=(Math.sin(fx*0.04+fy*0.025+t*0.8)+Math.sin(fx*0.03-fy*0.04+t*1.1))/2+Math.sin((fx+fy)*0.12+t*2.5)*0.2+Math.sin((fx-fy)*0.1-t*2)*0.2+Math.sin(fx*0.07+t*1.5)*Math.cos(fy*0.06-t*1.2)*0.15;
  const dist=Math.sqrt((fx-cx)**2+(fy-cy)**2),ang=Math.atan2(fy-cy,fx-cx);
