  const reaction=Math.tanh((act-inh*0.7+bg*0.3+spiral+act2*0.3-inh2*0.2)*2.2);
  const fineR=Math.tanh((act2-inh2*0.8+Math.sin(fx*0.1+fy*0.08)*0.5)*2.5);
  const cell=Math.tanh((Math.sin(fx*0.15)*Math.sin(fy*0.15)+Math.sin((fx+fy)*0.1+t)*0.5)*1.5)*0.3;
  const blend=reaction*0.6+fineR*0.15+cell*0.15+Math.tanh(spiral)*0.1,v=blend*0.5+0.5;
  const edge=Math.abs(reaction)>0.65?1.2:Math.abs(reaction)>0.4?1.05:0.95;
  const glow=Math.max(0,Math.abs(reaction)-0.5)*0.6;
  const pal=[[6,14,52],[12,48,82],[18,90,108],[28,140,138],[55,175,155],[140,195,130],[210,190,80],[225,155,65],[210,105,65],[175,65,75],[110,35,70],[55,20,60],[6,14,52]];
  const idx=v*(pal.length-1),i=Math.min(idx|0,pal.length-2),f=idx-i;
  const lum=0.85+Math.sin(reaction*Math.PI)*0.15+glow*0.3,ef=edge+glow*0.3;
  return[Math.min(255,(pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum*ef)|0,Math.min(255,(pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum*ef)|0,Math.min(255,(pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum*ef)|0];
}
